package cn.zhuatech.property.service;import jakarta.validation.constraints.NotBlank;import org.springframework.stereotype.Service;import java.util.*;
@Service public class TenantMoveInReadinessService{public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.leaseSigned())b.add("租赁合同未签署");if(!r.depositReceived())b.add("押金或履约担保未到账");if(!r.tenantIdentityVerified())b.add("租户主体身份未核验");if(!r.insuranceValid())b.add("要求的保险未生效");if(!r.fireSafetyAccepted())b.add("消防与安全交底未验收");if(!b.isEmpty()){a.add("阻止入驻并关闭合同、资金、身份和安全问题");return new Assessment(Decision.BLOCKED,b,a);}if(!r.accessProvisioned()||!r.utilitiesReady()||!r.initialDefectsRecorded()||!r.privacyNoticeAcknowledged()){if(!r.accessProvisioned())a.add("配置人员车辆和门禁权限");if(!r.utilitiesReady())a.add("确认水电网络等服务可用");if(!r.initialDefectsRecorded())a.add("完成交付查验和初始缺陷记录");if(!r.privacyNoticeAcknowledged())a.add("完成园区隐私告知确认");return new Assessment(Decision.REVIEW,b,a);}a.add("批准入驻并冻结租约、交付和权限快照");return new Assessment(Decision.MOVE_IN,b,a);}public record Request(@NotBlank String leaseNo,boolean leaseSigned,boolean depositReceived,boolean tenantIdentityVerified,boolean insuranceValid,boolean fireSafetyAccepted,boolean accessProvisioned,boolean utilitiesReady,boolean initialDefectsRecorded,boolean privacyNoticeAcknowledged){}public record Assessment(Decision decision,List<String>blockers,List<String>actions){}public enum Decision{MOVE_IN,REVIEW,BLOCKED}}
